-- Child task rows, Migration B (20261116100000_child_task_rows_b.sql): the JSON-subtasks cutover.
-- Run as postgres against the full Taskfold schema after the migration (local `supabase db reset`, then
-- `psql -v ON_ERROR_STOP=1 -f supabase/tests/child_task_rows_b.sql`). One rolled-back transaction;
-- reserved UUID prefix c41d0c0b-; example.invalid identities only.
-- The fixture block below is a verbatim copy of TaskfoldTests/Fixtures/legacy_subtasks.json (generated by
-- Scripts/legacy_subtasks_fixture.py with Python's hashlib, independent of the Swift and SQL code under test).
-- Keep it byte-identical: `python3 Scripts/legacy_subtasks_fixture.py` regenerates both (and git diff shows drift).
-- Cast: A owns everything and shares project S with B (accepted). C is an outsider. P is private, TP a team project.
-- Historical since Migration C dropped `subtasks`: on a post-C schema this file skips itself (psql \if).
select not exists (select 1 from pg_catalog.pg_attribute where attrelid = 'public.tasks'::regclass and attname = 'subtasks' and not attisdropped) as child_rows_c_applied \gset
\if :child_rows_c_applied
\echo 'child_task_rows_b: skipped (Migration C dropped the JSON subtasks this cutover converts)'
\q
\endif
begin;

create function public.zz_u(n integer) returns uuid language sql immutable as
$$ select ('c41d0c0b-0000-4000-8000-' || lpad(to_hex(n), 12, '0'))::uuid $$;

insert into auth.users(id,email) values
 (public.zz_u(1),'taskfold-cutover-owner@example.invalid'),
 (public.zz_u(2),'taskfold-cutover-member@example.invalid'),
 (public.zz_u(3),'taskfold-cutover-outsider@example.invalid');
insert into public.projects(id,user_id,name) values
 (public.zz_u(100),public.zz_u(1),'S shared'),
 (public.zz_u(102),public.zz_u(1),'P private'),
 (public.zz_u(104),public.zz_u(1),'TP team');
select set_config('request.jwt.claim.sub',public.zz_u(1)::text,true);
insert into public.project_collaborators(id,project_id,invited_email,invited_by) values
 (public.zz_u(110),public.zz_u(100),'taskfold-cutover-member@example.invalid',auth.uid());
select set_config('request.jwt.claim.sub',public.zz_u(2)::text,true);
update public.project_collaborators set status='accepted' where id=public.zz_u(110);
select set_config('request.jwt.claim.sub','',true);
insert into public.sections(id,user_id,project_id,name) values (public.zz_u(120),public.zz_u(1),public.zz_u(100),'S section');
insert into taskfold_private.teams(id,owner_id,name) values (public.zz_u(130),public.zz_u(1),'Synthetic team');
insert into taskfold_private.team_members(team_id,user_id,role) values (public.zz_u(130),public.zz_u(1),'admin');
insert into taskfold_private.team_content_projects(project_id,team_id) values (public.zz_u(104),public.zz_u(130));

create function public.zz_expect(sql text, expected_state text, fragment text default '') returns void
language plpgsql as $$
begin
 begin execute sql;
 exception when others then
  if sqlstate <> expected_state or position(fragment in sqlerrm) = 0 then
   raise exception 'Wrong failure for [%]: % %', sql, sqlstate, sqlerrm; end if;
  return;
 end;
 raise exception 'Expected failure was not raised: %', sql;
end $$;
-- Full baseline the way a current client sends it, or without the Migration A keys (an old client).
create function public.zz_base(id uuid, old_client boolean default false) returns jsonb language sql stable as $$
 select case when old_client then to_jsonb(t) - 'parent_id' - 'child_order' else to_jsonb(t) end from public.tasks t where t.id=zz_base.id $$;
-- Everything the conversion may touch for the synthetic accounts, as one digest (for the idempotency proof).
create function public.zz_digest() returns text language sql stable as $$
 select md5(coalesce((select string_agg(to_jsonb(t)::text, '|' order by t.id) from public.tasks t where t.user_id between public.zz_u(1) and public.zz_u(3)),'')
  || coalesce((select string_agg(to_jsonb(c)::text, '|' order by c.root_id) from taskfold_private.json_subtask_conversions c where c.root_user_id between public.zz_u(1) and public.zz_u(3)),'')
  || coalesce((select string_agg(to_jsonb(v)::text, '|' order by v.id) from public.view_orders v where v.user_id between public.zz_u(1) and public.zz_u(3)),'')
  || coalesce((select string_agg(to_jsonb(r)::text, '|' order by r.view_id) from taskfold_private.json_subtask_view_order_remaps r where r.user_id between public.zz_u(1) and public.zz_u(3)),'')
  || (select count(*)::text from public.task_activity) || (select count(*)::text from public.task_node_activity)
  || (select to_jsonb(c)::text from taskfold_private.child_task_record_config c)) $$;

-- 1. Structure, privileges, retired child-record system.
do $$
declare
 fn text;
 legacy text[] := array[
  'public.taskfold_read_child_tasks(uuid,uuid)', 'public.taskfold_edit_child_task(jsonb)', 'public.taskfold_close_child_task_edit(jsonb)',
  'public.taskfold_complete_child_task(jsonb)', 'public.taskfold_close_child_completion(jsonb)', 'public.taskfold_read_child_structure(uuid,uuid)',
  'public.taskfold_close_child_structure(jsonb)', 'public.taskfold_edit_child_structure(jsonb)', 'public.taskfold_forget_child_structure_undo(uuid)',
  'public.taskfold_child_structure_undo_archives()', 'public.taskfold_transfer_child(text,jsonb)', 'public.taskfold_review_child_adoption(uuid,uuid)',
  'public.taskfold_adopt_child_records(text,jsonb)', 'public.taskfold_child_adoption_targets(uuid,integer,uuid)', 'public.taskfold_complete_child_tasks(jsonb)',
  'public.taskfold_close_child_completion_batch(jsonb)', 'public.taskfold_read_completion_selection_roots(jsonb)', 'public.taskfold_complete_mixed_tasks(jsonb)',
  'public.taskfold_close_mixed_completion(jsonb)', 'public.taskfold_undo_mixed_completion(jsonb)', 'public.taskfold_review_child_copies(jsonb)',
  'public.taskfold_preview_child_repair(jsonb)', 'public.taskfold_child_steps(text,jsonb)', 'public.taskfold_child_steps_available(uuid,uuid)',
  'public.taskfold_search_child_adoption_targets(text,uuid,integer)', 'public.taskfold_child_repair_archives(uuid,integer)',
  'public.taskfold_child_repair_original(uuid,uuid)', 'public.taskfold_child_repair_original_cleanup(text,uuid,uuid,text,integer)',
  'public.taskfold_compare_child_repair_original(uuid,uuid)', 'public.taskfold_review_child_restore(text,uuid,uuid,uuid)',
  'public.taskfold_restore_child_original(text,jsonb)', 'public.taskfold_review_restored_child_copies(jsonb,uuid,uuid)',
  'public.taskfold_repair_children(text,jsonb)', 'public.taskfold_child_restore_status(jsonb,uuid,uuid)'];
 -- RPCs the child-rows builds (TaskTree.rowsEnabled) still call: they must stay executable.
 kept text[] := array['public.taskfold_patch_task(uuid,jsonb,jsonb)', 'public.taskfold_delete_task(uuid,jsonb)', 'public.taskfold_assign_task_scoped(uuid,jsonb,uuid,uuid)',
  'public.taskfold_import_todoist(text,jsonb)'];
 rel text;
begin
 foreach rel in array array['taskfold_private.json_subtask_conversions','taskfold_private.json_subtask_view_order_remaps','taskfold_private.child_rows_cutover'] loop
  if not (select relrowsecurity from pg_class where oid=rel::regclass) then raise exception '% must have RLS on', rel; end if;
  if has_table_privilege('authenticated',rel,'select') or has_table_privilege('anon',rel,'select') or has_table_privilege('service_role',rel,'select') then raise exception '% must have no grants', rel; end if;
 end loop;
 foreach fn in array array['taskfold_private.legacy_child_id(text,text[])','taskfold_private.legacy_child_plan(jsonb,jsonb)','taskfold_private.convert_json_subtasks()',
   'taskfold_private.remap_subtask_view_orders()','taskfold_private.guard_frozen_subtasks()','taskfold_private.legacy_reference_child_id(text)'] loop
  if has_function_privilege('authenticated',fn,'execute') or has_function_privilege('anon',fn,'execute') or has_function_privilege('service_role',fn,'execute') then raise exception '% exposed', fn; end if;
 end loop;
 if array_length(legacy,1) <> 34 then raise exception 'legacy list changed'; end if;
 foreach fn in array legacy loop
  if has_function_privilege('authenticated',fn,'execute') or has_function_privilege('anon',fn,'execute') then raise exception 'legacy child RPC % still executable', fn; end if;
 end loop;
 if (select revoked_functions from taskfold_private.child_rows_cutover) is distinct from legacy then raise exception 'back-out list differs from the revoked RPCs'; end if;
 foreach fn in array kept loop
  if to_regprocedure(fn) is not null and not has_function_privilege('authenticated',fn,'execute') then raise exception 'RPC % used by child-rows builds was revoked', fn; end if;
 end loop;
 if exists (select 1 from jsonb_each(to_jsonb((select c from taskfold_private.child_task_record_config c))) e where e.key like '%\_enabled' and e.value <> 'false'::jsonb) then
  raise exception 'a child_task_record_config flag is still on'; end if;
 if not exists (select 1 from pg_trigger where tgrelid='public.tasks'::regclass and tgname='aaa_taskfold_subtasks_frozen' and tgenabled='O') then raise exception 'freeze trigger missing'; end if;
 if (select count(*) from pg_trigger where tgrelid='public.tasks'::regclass and tgname in('zz_taskfold_webhook_capture','taskfold_capture_node_activity','taskfold_capture_activity','taskfold_team_content_task') and tgenabled='O') <> 4 then
  raise exception 'capture triggers must be enabled after the migration'; end if;
 if position('TASKFOLD_SCOPED_ASSIGNMENT_GUARD_V1' in pg_get_functiondef('public.taskfold_patch_task(uuid,jsonb,jsonb)'::regprocedure)) = 0 then raise exception 'scoped-assignment marker lost'; end if;
 if position('TASKFOLD_IMPORT_CHILD_ROWS_V1' in pg_get_functiondef('public.taskfold_import_todoist(text,jsonb)'::regprocedure)) = 0 then raise exception 'import patch missing'; end if;
 -- A revoked RPC answers 42501 (which the apps treat like the old PT503 "unavailable").
 perform set_config('request.jwt.claim.sub',public.zz_u(1)::text,true);
 set local role authenticated;
 perform public.zz_expect($q$select public.taskfold_read_child_tasks(gen_random_uuid(), null)$q$,'42501','permission denied');
 reset role;
 perform set_config('request.jwt.claim.sub','',true);
end $$;

