$json$::jsonb $fixture$;

do $$
declare c jsonb; tree jsonb; plan jsonb; e jsonb; a jsonb; i integer; k text; checked integer := 0;
begin
 for c in select value from jsonb_array_elements(public.zz_fixture()->'id_cases') loop
  if taskfold_private.legacy_child_id(c->>'root', array(select jsonb_array_elements_text(c->'path')))::text is distinct from c->>'expected' then
   raise exception 'id case % differs', c; end if;
  checked := checked + 1;
 end loop;
 for tree in select value from jsonb_array_elements(public.zz_fixture()->'trees') loop
  plan := taskfold_private.legacy_child_plan(tree->'root', tree->'subtasks');
  if jsonb_array_length(plan->'rows') is distinct from jsonb_array_length(tree->'expected_rows') then
   raise exception 'tree %: % rows, expected %', tree->>'name', jsonb_array_length(plan->'rows'), jsonb_array_length(tree->'expected_rows'); end if;
  for i in 0 .. jsonb_array_length(tree->'expected_rows') - 1 loop
   e := tree->'expected_rows'->i; a := plan->'rows'->i;
   if a->'row'->>'id' is distinct from e->>'id' or lower(a->'row'->>'parent_id') is distinct from lower(e->>'parent_id') or (a->'row'->>'child_order')::numeric is distinct from (e->>'child_order')::numeric
      or a->'row'->>'title' is distinct from e->>'title' or a->'path' is distinct from e->'path' or (a->>'level')::int is distinct from (e->>'level')::int
      or a->'row'->'completed' is distinct from e->'completed' or a->'row'->'source_metadata' is distinct from e->'source_metadata'
      -- The fixture's stand-in for check_task_assignment: an assignee survives when the root has a project.
      or (case when tree->'root'->>'project_id' is not null then a->'row'->'assigned_to' end) is distinct from nullif(e->'assigned_to','null'::jsonb) then
    raise exception 'tree % row %: got % expected %', tree->>'name', i, a, e; end if;
   foreach k in array array['description','priority','due_date','labels','is_heading'] loop
    if (e->'fields') ? k then
     if a->'row'->k is distinct from e->'fields'->k then raise exception 'tree % row % field %: got % expected %', tree->>'name', i, k, a->'row'->k, e->'fields'->k; end if;
    elsif a->'row'->k is distinct from (case k when 'description' then '""'::jsonb when 'priority' then '4'::jsonb when 'labels' then '[]'::jsonb else null end) then
     raise exception 'tree % row % field % should be the default, got %', tree->>'name', i, k, a->'row'->k;
    end if;
   end loop;
   if a->'row'->>'task_generation' is distinct from taskfold_private.legacy_child_id(tree->'root'->>'id', array(select jsonb_array_elements_text(e->'path')) || 'generation'::text)::text then
    raise exception 'tree % row % generation differs', tree->>'name', i; end if;
   checked := checked + 1;
  end loop;
  if plan->'skipped' is distinct from tree->'expected_skipped' then raise exception 'tree % skipped: got % expected %', tree->>'name', plan->'skipped', tree->'expected_skipped'; end if;
  if jsonb_array_length(plan->'reparented') is distinct from jsonb_array_length(tree->'expected_reparented') then raise exception 'tree % reparented count differs', tree->>'name'; end if;
  for i in 0 .. jsonb_array_length(tree->'expected_reparented') - 1 loop
   e := tree->'expected_reparented'->i; a := plan->'reparented'->i;
   if a->>'id' is distinct from e->>'id' or a->'path' is distinct from e->'path' or a->'level' is distinct from e->'level' or lower(a->>'parent') is distinct from lower(e->>'parent') then
    raise exception 'tree % reparented %: got % expected %', tree->>'name', i, a, e; end if;
  end loop;
 end loop;
 for c in select value from jsonb_array_elements(public.zz_fixture()->'references') loop
  if taskfold_private.legacy_reference_child_id(c->>'reference')::text is distinct from c->>'direct_id' then raise exception 'reference % differs', c; end if;
  select value into tree from jsonb_array_elements(public.zz_fixture()->'trees') where value->>'name' = c->>'tree';
  if (select x->'row'->>'id' from jsonb_array_elements(taskfold_private.legacy_child_plan(tree->'root', tree->'subtasks')->'rows') x
      where x->'row'->>'id' = c->>'direct_id') is distinct from c->>'expected_with_tree' then raise exception 'reference % resolution differs', c; end if;
 end loop;
 if checked < 70 then raise exception 'fixture parity checked only % ids', checked; end if;
 if taskfold_private.legacy_reference_child_id('subtask:not base64!') is not null or taskfold_private.legacy_reference_child_id('work:abc') is not null then raise exception 'malformed references must map to NULL'; end if;
end $$;

-- 3. The conversion on real rows. JSON trees are written as the SQL operator (the freeze trusts operators).
-- R1 carries legacy states today's guards refuse on new writes (a stale outsider assignee, a completed nested
-- heading), so the setup insert skips those two guards. The conversion itself runs with every guard on.
alter table public.tasks disable trigger taskfold_guard_task, disable trigger taskfold_guard_task_headings;
insert into public.tasks(id,user_id,title,project_id,section_id,subtasks,created_at) values
 (public.zz_u(1000),public.zz_u(1),'R1 shared root',public.zz_u(100),public.zz_u(120),jsonb_build_array(
   jsonb_build_object('id','a','title','Assigned to member','assigned_to',public.zz_u(2),'priority',2,'colour','red','subtasks',jsonb_build_array(
     jsonb_build_object('id','a1','title','Grandchild','due_date','2026-12-01'),
     jsonb_build_object('id','h','title','Done heading','is_heading',true,'completed',true))),
   jsonb_build_object('id','b','title','Assigned to outsider','assigned_to',public.zz_u(3)),
   42,
   jsonb_build_object('id','n','subtasks',jsonb_build_array(jsonb_build_object('id','lost','title','Lost'))),
   jsonb_build_object('id','d','title','Dup 1'), jsonb_build_object('id','d','title','Dup 2'),
   '   ',
   jsonb_build_object('id','p','title','Bad values','priority',9,'due_date','not a date')),'2026-01-02T03:04:05Z'),
 (public.zz_u(4000),public.zz_u(1),'R4 inbox root',null,null,jsonb_build_array(jsonb_build_object('id','x','title','Inbox child','assigned_to',public.zz_u(1))),now()),
 (public.zz_u(5000),public.zz_u(1),'RT team root',public.zz_u(104),null,'[{"id":"t","title":"Team child"}]',now()),
 (public.zz_u(6000),public.zz_u(1),'R6 odd root',public.zz_u(100),null,'{"weird":true}',now()),
 (public.zz_u(7000),public.zz_u(1),'R7 imported root',public.zz_u(102),null,
   '[{"id":"td","title":"Todoist child","source_metadata":{"provider":"todoist","account":"acct-1","original":{"id":"td-child"}}}]',now());
alter table public.tasks enable trigger taskfold_guard_task, enable trigger taskfold_guard_task_headings;
-- Depth: a 12-level chain and a 34-level chain (re-parenting below level 10, depth_over_32 below level 32).
insert into public.tasks(id,user_id,title,project_id,subtasks)
select public.zz_u(n),public.zz_u(1),'deep root',public.zz_u(102),(
 with recursive c(d, node) as (select depth, jsonb_build_object('id','n'||depth,'title','Level '||depth)
  union all select d-1, jsonb_build_object('id','n'||(d-1),'title','Level '||(d-1),'subtasks',jsonb_build_array(node)) from c where d>1)
 select jsonb_build_array(node) from c where d=1)
from (values (2000,12),(3000,34)) v(n,depth);
-- A view order that persisted virtual ids (as the old apps did for nested list ordering).
insert into public.view_orders(user_id,id,ids) values (public.zz_u(1),'project:S',jsonb_build_array(
 public.zz_u(1000)::text,
 'subtask:WyJjNDFkMGMwYi0wMDAwLTQwMDAtODAwMC0wMDAwMDAwMDAzZTgiLCJhIl0=',
 'subtask:WyJjNDFkMGMwYi0wMDAwLTQwMDAtODAwMC0wMDAwMDAwMDAzZTgiLCJuIl0=',
 'subtask:WyJjNDFkMGMwYi0wMDAwLTQwMDAtODAwMC0wMDAwMDAwMDAzZTgiLCJhIiwiYTEiXQ==',
 '442ce064-ea0f-3969-77b3-8c16986a3198',
 'unrelated'));

create temporary table zz_activity_before on commit drop as
 select (select count(*) from public.task_activity) activity, (select count(*) from public.task_node_activity) node_activity;

do $$
declare s jsonb; r public.tasks; c taskfold_private.json_subtask_conversions; v jsonb; deepest integer;
begin
 s := taskfold_private.convert_json_subtasks();
 -- Since Migration T (phase T) team trees convert too; nothing is deferred.
 if (s->>'roots')::int < 7 or (s->>'deferred_team_roots')::int <> 0 then raise exception 'conversion summary %', s; end if;
 if taskfold_private.remap_subtask_view_orders() < 1 then raise exception 'view order not remapped'; end if;
 if (select count(*) from pg_trigger where tgrelid='public.tasks'::regclass and tgname in('zz_taskfold_webhook_capture','taskfold_capture_node_activity','taskfold_capture_activity') and tgenabled='O') is distinct from 3 then
  raise exception 'capture triggers were not re-enabled'; end if;
 if (select activity from zz_activity_before) is distinct from (select count(*) from public.task_activity) or (select node_activity from zz_activity_before) is distinct from (select count(*) from public.task_node_activity) then
  raise exception 'the conversion recorded activity'; end if;

 -- R1: ids recomputed independently with Python's md5 (not by the function under test).
 if (select count(*) from public.tasks where parent_id is not null and id in(
      '99142f1a-b74a-92ed-0ef7-4b8f14446a8a','442ce064-ea0f-3969-77b3-8c16986a3198','741c17be-1f61-1950-1bca-5f8baad2b6be','2a8325ab-5cfd-eccf-4e73-449cba1d2353',
      '9f40acaf-6ac4-bf74-2de6-b2430cf181e4','164e466f-253f-acca-4b52-89be1e5a4a0e','6fa22833-64a7-a83f-aedb-ec5d01aeb17e')) <> 7 then raise exception 'R1 rows missing'; end if;
 select * into r from public.tasks where id='99142f1a-b74a-92ed-0ef7-4b8f14446a8a';
 if r.parent_id is distinct from public.zz_u(1000) or r.child_order is distinct from 1 or r.project_id is distinct from public.zz_u(100) or r.section_id is distinct from public.zz_u(120) or r.user_id is distinct from public.zz_u(1)
    or r.assigned_to is distinct from public.zz_u(2) or r.priority is distinct from 2 or r.source_metadata is distinct from '{"taskfold_legacy_child":{"colour":"red"}}'
    or r.task_generation is distinct from 'a81b9f4c-5c3d-af28-b750-46a42e33745b' or r.created_at is distinct from '2026-01-02T03:04:05Z' or r.subtasks is distinct from '[]' or r.completion_version is distinct from 0 then
  raise exception 'R1 child a fields wrong: %', to_jsonb(r); end if;
 select * into r from public.tasks where id='442ce064-ea0f-3969-77b3-8c16986a3198';
 if r.parent_id is distinct from '99142f1a-b74a-92ed-0ef7-4b8f14446a8a' or r.due_date is distinct from '2026-12-01' or r.child_order is distinct from 1 then raise exception 'R1 grandchild wrong'; end if;
 select * into r from public.tasks where id='741c17be-1f61-1950-1bca-5f8baad2b6be';
 if r.is_heading is not true or r.completed or r.source_metadata is distinct from '{"taskfold_legacy_child":{"completed":true}}' then raise exception 'completed heading not kept open: %', to_jsonb(r); end if;
 -- check_task_assignment decides: the outsider assignee is dropped and recorded.
 if (select assigned_to from public.tasks where id='2a8325ab-5cfd-eccf-4e73-449cba1d2353') is not null then raise exception 'outsider assignee kept'; end if;
 select * into r from public.tasks where id='6fa22833-64a7-a83f-aedb-ec5d01aeb17e';
 if r.priority is distinct from 4 or r.due_date is not null or r.source_metadata is distinct from '{"taskfold_legacy_child":{"priority":9,"due_date":"not a date"}}' then raise exception 'unfit values not kept aside: %', to_jsonb(r); end if;
 if (select title from public.tasks where id='9f40acaf-6ac4-bf74-2de6-b2430cf181e4') is distinct from 'Dup 1' or (select title from public.tasks where id='164e466f-253f-acca-4b52-89be1e5a4a0e') is distinct from 'Dup 2' then raise exception 'duplicate sibling ids'; end if;
 select * into c from taskfold_private.json_subtask_conversions where root_id=public.zz_u(1000);
 if c.status is distinct from 'converted' or cardinality(c.child_ids) is distinct from 7 or c.original->0->>'title' is distinct from 'Assigned to member' or c.converted_at is null then raise exception 'R1 archive wrong: %', to_jsonb(c); end if;
 if (select jsonb_agg(x->>'reason' order by x->>'reason') from jsonb_array_elements(c.skipped->'skipped') x) is distinct from '["empty_title","missing_title","not_an_object"]' then raise exception 'junk not recorded: %', c.skipped; end if;
 if (select (x->>'descendants')::int from jsonb_array_elements(c.skipped->'skipped') x where x->>'reason'='missing_title') is distinct from 1 then raise exception 'lost branch not counted'; end if;
 if jsonb_array_length(c.skipped->'assignees_dropped') is distinct from 1 or c.skipped->'assignees_dropped'->0->>'assigned_to' is distinct from public.zz_u(3)::text then raise exception 'dropped assignee not recorded'; end if;
 if (select subtasks from public.tasks where id=public.zz_u(1000)) is distinct from '[]' then raise exception 'R1 tree not cleared'; end if;

 -- Inbox: a self-assignee passes check_task_assignment; children inherit the null project.
 select * into r from public.tasks where id='c69248f4-a4c8-781a-7ec4-05836ddde5ce';
 if r.parent_id is distinct from public.zz_u(4000) or r.project_id is not null or r.assigned_to is distinct from public.zz_u(1) then raise exception 'inbox child wrong'; end if;
 -- Team (since Migration T): converted like any root, the child row is team content.
 select * into c from taskfold_private.json_subtask_conversions where root_id=public.zz_u(5000);
 if c.status is distinct from 'converted' or (select subtasks from public.tasks where id=public.zz_u(5000)) is distinct from '[]'
    or not exists(select 1 from public.tasks x join taskfold_private.team_content_tasks k on k.task_id=x.id where x.parent_id=public.zz_u(5000)
                  and x.id=taskfold_private.legacy_child_id(public.zz_u(5000)::text,array['t'])) then raise exception 'team root not converted'; end if;
 -- A non-list tree is archived and cleared.
 if (select skipped->>'reason' from taskfold_private.json_subtask_conversions where root_id=public.zz_u(6000)) is distinct from 'not_a_list' or (select subtasks from public.tasks where id=public.zz_u(6000)) is distinct from '[]' then raise exception 'odd root'; end if;
 -- Unknown keys (a Todoist import's own metadata) move to source_metadata.taskfold_legacy_child.
 if (select source_metadata->'taskfold_legacy_child'->'source_metadata'->'original'->>'id' from public.tasks where id='fe47d04d-7843-3a16-d610-d05950233cce') is distinct from 'td-child' then raise exception 'imported metadata lost'; end if;

 -- Depth: levels 11 and 12 hang from the level-9 node, ordered 1001, 1002; nothing exceeds 10 ancestors.
 if (select count(*) from public.tasks where parent_id='da43e5c1-b856-08db-aa92-367723b4d787' and child_order in (1001,1002)) is distinct from 2 then raise exception 'depth re-parenting wrong'; end if;
 if (select parent_id from public.tasks where id='fd057572-afe5-f484-3ef1-eda8cdf62f14') is distinct from 'da43e5c1-b856-08db-aa92-367723b4d787' then raise exception 'level-12 node not re-parented'; end if;
 if jsonb_array_length((select skipped->'reparented' from taskfold_private.json_subtask_conversions where root_id=public.zz_u(2000))) is distinct from 2 then raise exception 'reparented not recorded'; end if;
 select * into c from taskfold_private.json_subtask_conversions where root_id=public.zz_u(3000);
 if cardinality(c.child_ids) is distinct from 32 or c.skipped->'skipped'->0->>'reason' is distinct from 'depth_over_32' or (c.skipped->'skipped'->0->>'descendants')::int is distinct from 1 or jsonb_array_length(c.skipped->'reparented') is distinct from 22 then
  raise exception 'depth_over_32 wrong: %', c.skipped; end if;
 with recursive up(id, parent_id, depth) as (select id, parent_id, 0 from public.tasks where id = any(c.child_ids)
  union all select up.id, t.parent_id, up.depth+1 from up join public.tasks t on t.id=up.parent_id where up.parent_id is not null)
 select max(depth) into deepest from up;
 if deepest is distinct from 10 then raise exception 'deepest converted node has % ancestors', deepest; end if;

 -- View order: resolvable references now name the rows, the unconverted one is kept, the duplicate is dropped.
 select ids into v from public.view_orders where user_id=public.zz_u(1) and id='project:S';
 if v is distinct from jsonb_build_array(public.zz_u(1000)::text,'99142f1a-b74a-92ed-0ef7-4b8f14446a8a','subtask:WyJjNDFkMGMwYi0wMDAwLTQwMDAtODAwMC0wMDAwMDAwMDAzZTgiLCJuIl0=','442ce064-ea0f-3969-77b3-8c16986a3198','unrelated') then
  raise exception 'view order remap wrong: %', v; end if;
 if not exists (select 1 from taskfold_private.json_subtask_view_order_remaps where user_id=public.zz_u(1) and view_id='project:S' and jsonb_array_length(original)=6) then raise exception 'remap not archived'; end if;
end $$;

-- 4. Idempotency: a second run converts nothing and changes nothing.
do $$
declare before text := public.zz_digest(); s jsonb;
begin
 s := taskfold_private.convert_json_subtasks();
 if s is distinct from '{"rows":0,"roots":0,"skipped":0,"rejected":0,"reparented":0,"deferred_team_roots":0}'::jsonb then raise exception 'second run was not a no-op: %', s; end if;
 if taskfold_private.remap_subtask_view_orders() is distinct from 0 then raise exception 'second remap changed view orders'; end if;
 if public.zz_digest() is distinct from before then raise exception 'second run changed data'; end if;
end $$;

-- 5. Freeze: requests cannot write JSON trees any more (inserts included); since Migration T team projects too.
do $$
declare t public.tasks;
begin
 perform set_config('request.jwt.claim.sub',public.zz_u(1)::text,true);
 perform public.zz_expect($q$update public.tasks set subtasks='[{"title":"x"}]' where id=public.zz_u(1000)$q$,'PT409','TASKFOLD_CONFLICT: Subtasks are now tasks. Update Taskfold to edit them.');
 perform public.zz_expect($q$insert into public.tasks(user_id,title,project_id,subtasks) values(public.zz_u(1),'json insert',public.zz_u(102),'[{"title":"x"}]')$q$,'PT409','Subtasks are now tasks');
 perform public.zz_expect($q$select public.taskfold_patch_task(public.zz_u(1000), public.zz_base(public.zz_u(1000)), '{"subtasks":[{"title":"x"}]}'::jsonb)$q$,'PT409','Subtasks are now tasks');
 -- Empty trees are still fine (old builds send them on every insert).
 insert into public.tasks(id,user_id,title,project_id,subtasks) values(public.zz_u(8000),public.zz_u(1),'plain insert',public.zz_u(102),'[]');
 update public.tasks set subtasks='[]' where id=public.zz_u(6000);
 -- Team trees are frozen too (Migration T); the freeze fires before the closed team-content guard.
 perform public.zz_expect($q$update public.tasks set subtasks='[{"id":"t","title":"Team edit"}]' where id=public.zz_u(5000)$q$,'PT409','Subtasks are now tasks');
 -- Service-role requests (automation, functions) are requests too.
 perform set_config('request.jwt.claim.sub','',true);
 perform set_config('request.jwt.claim.role','service_role',true);
 perform public.zz_expect($q$update public.tasks set subtasks='[{"title":"x"}]' where id=public.zz_u(1000)$q$,'PT409','Subtasks are now tasks');
 perform set_config('request.jwt.claim.role','',true);
 -- The SQL operator (back-out script) is trusted.
 update public.tasks set subtasks='[{"title":"operator"}]' where id=public.zz_u(8000);
 update public.tasks set subtasks='[]' where id=public.zz_u(8000);
end $$;

-- 6. Old clients on converted rows: PATCH and DELETE keep working with old-shape baselines.
do $$
declare t public.tasks;
begin
 perform set_config('request.jwt.claim.sub',public.zz_u(1)::text,true);
 -- Owner renames a converted child with an old-shape baseline: the structure is untouched.
 t := public.taskfold_patch_task('9f40acaf-6ac4-bf74-2de6-b2430cf181e4', public.zz_base('9f40acaf-6ac4-bf74-2de6-b2430cf181e4',true), '{"title":"renamed by old build","completed":true}'::jsonb);
 if t.title is distinct from 'renamed by old build' or not t.completed or t.parent_id is distinct from public.zz_u(1000) or t.child_order is distinct from 5 then raise exception 'old-client child patch: %', to_jsonb(t); end if;
 -- Old client completes the converted root (its synced subtasks are now []).
 t := public.taskfold_patch_task(public.zz_u(1000), public.zz_base(public.zz_u(1000),true), '{"completed":true}'::jsonb);
 if not t.completed or t.subtasks is distinct from '[]' then raise exception 'old-client root patch'; end if;
 -- The shared-project member edits a converted child too.
 perform set_config('request.jwt.claim.sub',public.zz_u(2)::text,true);
 t := public.taskfold_patch_task('164e466f-253f-acca-4b52-89be1e5a4a0e', public.zz_base('164e466f-253f-acca-4b52-89be1e5a4a0e',true), '{"priority":1}'::jsonb);
 if t.priority is distinct from 1 or t.parent_id is distinct from public.zz_u(1000) then raise exception 'member patch of a converted child'; end if;
 perform set_config('request.jwt.claim.sub',public.zz_u(1)::text,true);
 -- DELETE: an old-shape baseline of a child conflicts (Migration A rule: visible conflict, never silent loss) ...
 perform public.zz_expect($q$select public.taskfold_delete_task('2a8325ab-5cfd-eccf-4e73-449cba1d2353', public.zz_base('2a8325ab-5cfd-eccf-4e73-449cba1d2353',true))$q$,'P0001','TASKFOLD_CONFLICT');
 -- ... a current baseline deletes it ...
 if not public.taskfold_delete_task('2a8325ab-5cfd-eccf-4e73-449cba1d2353', public.zz_base('2a8325ab-5cfd-eccf-4e73-449cba1d2353')) then raise exception 'child delete failed'; end if;
 -- ... and an old-shape baseline of the converted root deletes the root and, by cascade, its children.
 if not public.taskfold_delete_task(public.zz_u(1000), public.zz_base(public.zz_u(1000),true)) then raise exception 'old-client root delete failed'; end if;
 if exists (select 1 from public.tasks where id in('99142f1a-b74a-92ed-0ef7-4b8f14446a8a','442ce064-ea0f-3969-77b3-8c16986a3198','9f40acaf-6ac4-bf74-2de6-b2430cf181e4')) then raise exception 'children survived the root delete'; end if;
 -- The archive outlives the root (back-out reports it instead of losing it).
 if not exists (select 1 from taskfold_private.json_subtask_conversions where root_id=public.zz_u(1000)) then raise exception 'archive lost with the root'; end if;
 perform set_config('request.jwt.claim.sub','',true);
end $$;

-- 7. Producers. Todoist import: children are rows; re-import and pre-cutover JSON children are never duplicated.
do $$
declare result jsonb; bundle jsonb;
begin
 perform set_config('request.jwt.claim.sub',public.zz_u(1)::text,true);
 bundle := jsonb_build_object('projects','[]'::jsonb,'sections','[]'::jsonb,'labels','[]'::jsonb,'tasks',jsonb_build_array(
  jsonb_build_object('source_id','td-root','subtask_count',2,'comment_count',0,'record',jsonb_build_object('id',public.zz_u(9000),'title','Imported root','project_id',public.zz_u(102),'subtasks','[]'::jsonb)),
  jsonb_build_object('source_id','td-kid','parent_source_id','td-root','subtask_count',0,'comment_count',0,'record',jsonb_build_object('id',public.zz_u(9001),'title','Imported kid','project_id',public.zz_u(102),'child_order',1,'subtasks','[]'::jsonb)),
  jsonb_build_object('source_id','td-grandkid','parent_source_id','td-kid','subtask_count',0,'comment_count',0,'record',jsonb_build_object('id',public.zz_u(9002),'title','Imported grandkid','project_id',public.zz_u(102),'child_order',1,'subtasks','[]'::jsonb)),
  -- Its parent was imported as JSON before the cutover and converted (R7 above): resolved through the archive metadata.
  jsonb_build_object('source_id','td-late','parent_source_id','td-child','subtask_count',0,'comment_count',0,'record',jsonb_build_object('id',public.zz_u(9003),'title','Late kid','project_id',public.zz_u(102),'child_order',2,'subtasks','[]'::jsonb)),
  -- Imported as JSON before the cutover: skipped, not duplicated.
  jsonb_build_object('source_id','td-child','parent_source_id','td-root-old','subtask_count',0,'comment_count',0,'record',jsonb_build_object('id',public.zz_u(9004),'title','Todoist child again','project_id',public.zz_u(102),'subtasks','[]'::jsonb)),
  -- Unknown parent: a standalone task.
  jsonb_build_object('source_id','td-orphan','parent_source_id','td-missing','subtask_count',0,'comment_count',0,'record',jsonb_build_object('id',public.zz_u(9005),'title','Orphan','project_id',public.zz_u(102),'child_order',3,'subtasks','[]'::jsonb))));
 result := public.taskfold_import_todoist('acct-1', bundle);
 if result->>'tasksImported' is distinct from '5' or result->>'tasksSkipped' is distinct from '1' then raise exception 'import counts: %', result; end if;
 if (select parent_id from public.tasks where id=public.zz_u(9001)) is distinct from public.zz_u(9000) or (select parent_id from public.tasks where id=public.zz_u(9002)) is distinct from public.zz_u(9001)
    or (select child_order from public.tasks where id=public.zz_u(9002)) is distinct from 1 then raise exception 'imported children not linked'; end if;
 if (select parent_id from public.tasks where id=public.zz_u(9003)) is distinct from 'fe47d04d-7843-3a16-d610-d05950233cce' then raise exception 'late child not linked to its converted parent'; end if;
 if exists (select 1 from public.tasks where id=public.zz_u(9004)) then raise exception 'pre-cutover child imported twice'; end if;
 if (select parent_id from public.tasks where id=public.zz_u(9005)) is not null or (select child_order from public.tasks where id=public.zz_u(9005)) is not null then raise exception 'orphan not standalone'; end if;
 result := public.taskfold_import_todoist('acct-1', bundle);
 if result->>'tasksImported' is distinct from '0' then raise exception 're-import duplicated: %', result; end if;
 -- An outdated function sending a JSON tree meets the freeze.
 perform public.zz_expect(format($q$select public.taskfold_import_todoist('acct-2', %L::jsonb)$q$, jsonb_build_object('projects','[]'::jsonb,'sections','[]'::jsonb,'labels','[]'::jsonb,'tasks',jsonb_build_array(
  jsonb_build_object('source_id','old','record',jsonb_build_object('id',public.zz_u(9010),'title','Old style','subtasks','[{"title":"nested"}]'::jsonb))))),'PT409','Subtasks are now tasks');
 perform set_config('request.jwt.claim.sub','',true);
end $$;

-- Automation API: parent_id/child_order are fields, the projection carries them, a parent delete is refused.
do $$
declare t public.tasks;
begin
 perform taskfold_private.automation_validate_fields(jsonb_build_object('parent_id',public.zz_u(9000),'child_order',2.5),null);
 perform taskfold_private.automation_validate_fields('{"parent_id":null,"child_order":null}'::jsonb,null);
 perform public.zz_expect($q$select taskfold_private.automation_validate_fields('{"parent_id":"nope"}'::jsonb,null)$q$,'22023','parent');
 perform public.zz_expect($q$select taskfold_private.automation_validate_fields('{"child_order":"1"}'::jsonb,null)$q$,'22023','order');
 select * into t from public.tasks where id=public.zz_u(9001);
 if taskfold_private.automation_task_projection(t)->>'parent_id' is distinct from public.zz_u(9000)::text or (taskfold_private.automation_task_projection(t)->>'child_order')::numeric is distinct from 1 then raise exception 'projection lacks the child fields'; end if;
 select * into t from public.tasks where id=public.zz_u(9000);
 perform public.zz_expect(format($q$select taskfold_private.automation_review_delete(%L,%L,%L,'[]'::jsonb)$q$, public.zz_u(1), public.zz_u(9000), taskfold_private.automation_task_revision(t)),'PT409','subtasks first');
 select * into t from public.tasks where id=public.zz_u(9002);
 perform taskfold_private.automation_review_delete(public.zz_u(1), public.zz_u(9002), taskfold_private.automation_task_revision(t), '[]'::jsonb);
 if position('base ?& array[''assigned_to'',''subtasks'',''section_id'']' in pg_get_functiondef('taskfold_private.automation_task_write(uuid,text,text,jsonb)'::regprocedure)) > 0 then raise exception 'automation moves still need a subtasks baseline'; end if;
end $$;

rollback;
